import {renewDeal} from './regional-contract-reviews.js?v=business-site-analysis-2';
import {contractQuote,PRICE_BANDS} from './regional-pricing.js?v=business-site-analysis-2';
import {NEIGHBOR_SIDES,neighborSupply} from './neighbor-economies.js?v=business-site-analysis-2';
import {connectionCandidates,addConnection,signDeal,cancelDeal,connected,terminationFee,NEIGHBORS} from './region.js?v=business-site-analysis-2';
import {recompute} from './engine.js?v=business-site-analysis-2';
export function showRegion(ui){const {city,dialog,update,save,clearUndo,notify}=ui,c=city(),$=s=>document.querySelector(s),fmt=v=>'§'+Math.round(v).toLocaleString(),candidates=connectionCandidates(c).filter(p=>!c.region.connections.some(e=>e.tile===p.tile&&e.kind===p.kind)),label=p=>`${NEIGHBORS[p.side]} · ${p.kind} · tile ${p.tile%c.size+1}, ${Math.floor(p.tile/c.size)+1}`;
 dialog('Neighbors & utility deals',`<p>Run a power line, pipe, road, highway or rail to a dry map boundary, then complete the neighbor connection here. Operating seaports can connect through navigable water. Each connection costs §100.</p><h3>Regional cities</h3><div class="table-scroll"><table><thead><tr><th>Neighbor</th><th>Population</th><th>Treasury</th><th>Power surplus</th><th>Water surplus</th><th>Disposal space</th><th>Last trade balance</th></tr></thead><tbody>${NEIGHBOR_SIDES.map(side=>{const n=c.region.neighbors[side];return `<tr><td>${NEIGHBORS[side]}</td><td>${side==='sea'?'Port network':Math.round(n.population).toLocaleString()}</td><td>${fmt(n.treasury)}</td><td>${neighborSupply(c,side,'power').toFixed(1)}</td><td>${neighborSupply(c,side,'water').toFixed(1)}</td><td>${neighborSupply(c,side,'garbage').toFixed(1)}</td><td>${fmt(n.lastTradeBalance)}</td></tr>`;}).join('')}</tbody></table></div><p>Neighbors grow and fund capacity from their own budgets. Their residents use utilities first; exports to you use remaining capacity. Resource and disposal shortages can reduce deliveries without charging you a supply-failure penalty. Regional values update monthly. Last trade balance is money received by that neighbor from our deals, minus payments to us.</p><label>Available border routes<select id="neighborRoute">${candidates.map((p,i)=>`<option value="${i}">${label(p)}</option>`).join('')||'<option value="">No unconnected border routes</option>'}</select></label><button id="connectNeighbor" ${candidates.length?'':'disabled'}>Complete connection · §100</button><h3>Proposed contract</h3><label>Connection<select id="dealConnection">${c.region.connections.map((p,i)=>`<option value="${i}" ${connected(c,p)?'':'disabled'}>${label(p)}${connected(c,p)?'':' · disconnected'}</option>`).join('')||'<option value="">Build a connection first</option>'}</select></label><label>Direction<select id="dealDirection"><option value="import">Import</option><option value="export">Export</option></select></label><label>Fixed monthly quantity for sales / incoming garbage<select id="dealAmount"><option value="25">25 units</option><option value="50" selected>50 units</option><option value="100">100 units</option></select></label><p id="dealTerms"></p><button id="acceptDeal" class="primary" ${c.region.connections.length?'':'disabled'}>Accept contract</button><h3>Active deals</h3>${c.region.deals.map(d=>{const con=c.region.connections[d.connection],buys=d.kind==='garbage'?d.direction==='export':d.direction==='import';return `<article class="milestone"><strong>${NEIGHBORS[con.side]} · ${d.direction} ${d.kind}</strong><p>${d.failed?'Connection or capacity failure: this deal will end with a penalty at the next monthly settlement.':`${d.delivered.toFixed(1)} units ${d.kind==='garbage'?'last month':'currently delivered'}. ${buys?'You pay':'You receive'} ${fmt(buys?Math.max(d.minFee,d.delivered*d.rate):(d.kind==='garbage'?d.delivered:d.amount)*d.rate)}/month.`}</p><p>Unit price: §${d.rate.toFixed(2)} · ${PRICE_BANDS[d.priceBand||'standard'].name}. Price stays fixed until you accept new terms.</p><p>${c.month>=d.issuedMonth+12?'Annual review reached: voluntary termination is free.':`Free termination after ${d.issuedMonth+12-c.month} more months.`}</p><button data-review-deal="${d.id}" ${c.month>=d.issuedMonth+12?'':'disabled'}>Review new terms</button><button data-cancel-deal="${d.id}">End deal · ${fmt(terminationFee(c,d))}</button></article>`;}).join('')||'<p>No contracts signed.</p>'}<h3>How deals work</h3><ul><li>Power and water imports cover the deficit on the connected network, limited by the neighbor’s available surplus. Unconnected districts receive nothing. Cheaper contracts supply each network first, with older contracts breaking price ties. Every signed import has its own minimum fee, even when it supplies zero units.</li><li>Power and water exports require local capacity for your city plus the promised quantity. Older export contracts have first claim on local surplus. Imported deficit supply is not resold. A broken connection or supply shortage cancels the affected deal with a penalty.</li><li>Garbage exports remove connected excess waste after local landfills have collected what they can, up to remaining neighbor disposal space. Cheaper reachable disposal contracts are used first. Undelivered waste stays in your city. Incoming garbage arrives at the connection, up to the agreed quantity and the neighbor’s available waste, and needs connected disposal capacity. Payments follow actual delivery.</li><li>Rail freight requires a connected train station linking the tracks to local roads. Seaports use their local road access.</li></ul><p>Regional income: ${fmt(c.stats.regionIncome)}/month. Charges: ${fmt(c.stats.regionExpense)}/month. Garbage projections use the previous collection; the actual bill changes with waste. Penalties paid: ${fmt(c.region.totalPenalties)}.</p><p class="fine">You can sign one deal per resource with each neighbor: up to four power, four water and five garbage contracts. Neighbor names, prices and annual review terms are provisional; neighbor populations, budgets, growth, resource use and investment are original aggregate simulations, not full neighboring tile maps or recovered original formulas.</p>`);
 function draft(){const index=Number($('#dealConnection').value),con=c.region.connections[index];return{index,con,kind:con&&['power','water'].includes(con.kind)?con.kind:'garbage',direction:$('#dealDirection').value,amount:Number($('#dealAmount').value)};}
 function terms(){const d=draft();if(!d.con){$('#acceptDeal').disabled=true;$('#dealTerms').textContent='Connect a border route to receive an offer.';return;}const existing=c.region.deals.find(deal=>deal.kind===d.kind&&c.region.connections[deal.connection].side===d.con.side);$('#acceptDeal').disabled=!!existing||!connected(c,d.con);if(existing){$('#dealTerms').textContent=`${NEIGHBORS[d.con.side]} already has your ${d.kind} contract. Review or end that deal below, or choose another neighbor.`;return;}const buys=d.kind==='garbage'?d.direction==='export':d.direction==='import',quote=contractQuote(c,d.con,d.kind,d.direction,d.amount),rate=quote.rate,min=quote.minFee,fee=quote.earlyFee;$('#dealTerms').textContent=`${d.direction==='import'?'Import':'Export'} ${d.kind}: ${buys?`pay §${rate} per delivered unit (minimum ${fmt(min)}/month)`:`receive ${fmt(d.amount*rate)}/month for ${d.amount} units`}. ${buys?'Quantity follows connected demand or excess garbage, limited by neighbor capacity.':'You must fulfill the fixed quantity.'} ${PRICE_BANDS[quote.priceBand].name} sets this offer. Accepted prices stay fixed. Early cancellation costs ${fmt(fee)}; voluntary termination is free after twelve months. Supply failure or connection loss carries the full penalty.`;}

 function review(id){const d=c.region.deals.find(d=>d.id===id),con=c.region.connections[d.connection];dialog('Review neighbor contract',`<p>${NEIGHBORS[con.side]} · ${d.direction} ${d.kind}. Current unit price: §${d.rate.toFixed(2)}. Your existing terms continue unless you accept a new offer or end the contract.</p><label>New quantity<select id="reviewQuantity">${[25,50,100].map(n=>`<option value="${n}" ${n===d.amount?'selected':''}>${n} units</option>`).join('')}</select></label><p>Quantity fixes power/water sales and caps incoming garbage. Utility purchases and garbage disposal follow actual connected demand, within neighbor capacity.</p><p id="reviewTerms"></p><p id="reviewError" role="alert"></p><div class="actions"><button id="acceptReview" class="primary">Accept new 12-month term</button><button id="keepReview">Keep current terms</button></div>`);function preview(){const amount=Number($('#reviewQuantity').value),q=contractQuote(c,con,d.kind,d.direction,amount);$('#reviewTerms').textContent=`New unit price: §${q.rate.toFixed(2)} (${PRICE_BANDS[q.priceBand].name}). Minimum buying fee: ${fmt(q.minFee)}/month. No renewal charge. Accepting resets the twelve-month term; early termination or a player supply/connection breach would cost ${fmt(q.earlyFee)}.`;}$('#reviewQuantity').onchange=preview;$('#keepReview').onclick=()=>showRegion(ui);$('#acceptReview').onclick=()=>{const result=renewDeal(c,id,Number($('#reviewQuantity').value));if(!result.ok){$('#reviewError').textContent=result.error;return;}notify('New neighbor terms accepted. The twelve-month term starts now.');changed();};preview();}
 function changed(){clearUndo();recompute(c);update();save();showRegion(ui);}
 $('#connectNeighbor').onclick=()=>{const p=candidates[Number($('#neighborRoute').value)];if(!p)return;const r=addConnection(c,p);if(!r.ok)return notify(r.error);notify('Neighbor connection completed.');changed();};$('#acceptDeal').onclick=()=>{const d=draft(),before=structuredClone(c.region),r=signDeal(c,d.index,d.kind,d.direction,d.amount);if(!r.ok)return notify(r.error);recompute(c);if(c.region.deals.at(-1).failed){c.region=before;recompute(c);return notify('There is not enough connected surplus to fulfill this offer. Add capacity first.');}notify('Neighbor contract accepted.');changed();};document.querySelectorAll('[data-review-deal]').forEach(b=>b.onclick=()=>review(Number(b.dataset.reviewDeal)));document.querySelectorAll('[data-cancel-deal]').forEach(b=>b.onclick=()=>{const r=cancelDeal(c,Number(b.dataset.cancelDeal));if(!r.ok)return notify(r.error);notify(`Deal ended. Fee: ${fmt(r.fee)}.`);changed();});for(const id of ['dealConnection','dealDirection','dealAmount'])$('#'+id).onchange=terms;terms();
}
